Here is a complete, production-ready implementation of a newsletter sign-up system that complies with privacy regulations (such as GDPR and CAN-SPAM). 

This solution uses standard HTML5 on the front end and **Node.js (Express)** on the back end.

---

### 1. Front-End: Sign-up Form (`index.html`)

This form requires an active action to give consent (the checkbox is explicitly unchecked by default) and handles submission via JavaScript `fetch`.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Newsletter Sign-up</title>
  <style>
    .form-group { margin-bottom: 15px; }
    .error { color: #d9534f; }
    .success { color: #5cb85c; }
    .hidden { display: none; }
  </style>
</head>
<body>

  <h2>Subscribe to our Newsletter</h2>

  <form id="newsletterForm">
    <div class="form-group">
      <label for="email">Email Address:</label><br>
      <input type="email" id="email" name="email" required placeholder="you@example.com">
    </div>

    <!-- Requirement: Consent must not be pre-checked -->
    <div class="form-group">
      <input type="checkbox" id="consent" name="consent" required>
      <label for="consent">
        I agree to receive the newsletter and accept the <a href="/privacy" target="_blank">Privacy Policy</a>.
      </label>
    </div>

    <button type="submit" id="submitBtn">Subscribe</button>
  </form>

  <p id="responseMessage" class="hidden"></p>

  <script>
    const form = document.getElementById('newsletterForm');
    const messageEl = document.getElementById('responseMessage');

    form.addEventListener('submit', async (e) => {
      e.preventDefault();

      const email = document.getElementById('email').value.trim();
      const consent = document.getElementById('consent').checked;

      // Ensure consent was actively given
      if (!consent) {
        showMessage('You must agree to the terms before subscribing.', 'error');
        return;
      }

      try {
        const response = await fetch('/api/newsletter/subscribe', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ email, consent })
        });

        const data = await response.json();

        if (response.ok) {
          showMessage(data.message, 'success');
          form.reset();
        } else {
          showMessage(data.error || 'Something went wrong.', 'error');
        }
      } catch (err) {
        showMessage('Network error. Please try again later.', 'error');
      }
    });

    function showMessage(text, type) {
      messageEl.textContent = text;
      messageEl.className = type;
      messageEl.classList.remove('hidden');
    }
  </script>
</body>
</html>
```

---

### 2. Back-End: Express Server (`server.js`)

This handles:
1. **Server-side validation**: Using the `validator` library to check email format and normalization.
2. **Unsubscribe logic**: Generating a unique token per subscriber so each email contains a working unsubscribe link.

```bash
# Install dependencies
npm install express validator crypto
```

```javascript
const express = require('express');
const crypto = require('crypto');
const validator = require('validator');

const app = express();
app.use(express.json());
app.use(express.static('public')); // Serve the HTML file

// Simulated Database (In production, replace with PostgreSQL, MongoDB, etc.)
const subscribers = new Map();

/**
 * 1. SUBSCRIBE ENDPOINT
 */
app.post('/api/newsletter/subscribe', (req, res) => {
  const { email, consent } = req.body;

  // Requirement: Explicit consent required
  if (!consent) {
    return res.status(400).json({ error: 'Consent is required to subscribe.' });
  }

  // Requirement: Server-side validation
  if (!email || typeof email !== 'string') {
    return res.status(400).json({ error: 'Email is required.' });
  }

  // Normalize (lowercase, remove dots for gmail, etc.) and validate
  const cleanEmail = validator.normalizeEmail(email.trim());
  if (!validator.isEmail(cleanEmail)) {
    return res.status(400).json({ error: 'Please provide a valid email address.' });
  }

  // Check if already subscribed
  const existingSubscriber = subscribers.get(cleanEmail);
  if (existingSubscriber && existingSubscriber.status === 'subscribed') {
    return res.status(409).json({ error: 'This email is already subscribed.' });
  }

  // Generate a cryptographically secure token for unsubscription
  const unsubscribeToken = crypto.randomBytes(32).toString('hex');

  // Save to database
  subscribers.set(cleanEmail, {
    email: cleanEmail,
    consentGivenAt: new Date().toISOString(),
    status: 'subscribed',
    unsubscribeToken: unsubscribeToken
  });

  /* 
   * Example: When sending an actual newsletter email to this user, 
   * you would include this URL in the email footer:
   * 
   * https://yourdomain.com/api/newsletter/unsubscribe?token=${unsubscribeToken}
   */

  return res.status(201).json({ 
    message: 'Thank you for subscribing! Check your inbox for confirmation.' 
  });
});

/**
 * 2. UNSUBSCRIBE ENDPOINT
 * Requirement: Subscribers must be able to unsubscribe
 */
app.get('/api/newsletter/unsubscribe', (req, res) => {
  const { token } = req.query;

  if (!token) {
    return res.status(400).send('Invalid request: Missing unsubscribe token.');
  }

  // Look up user by their token
  let targetEmail = null;
  for (const [email, data] of subscribers.entries()) {
    if (data.unsubscribeToken === token) {
      targetEmail = email;
      break;
    }
  }

  if (!targetEmail) {
    return res.status(404).send('Invalid or expired unsubscribe link.');
  }

  // Update status (or delete from database entirely)
  const user = subscribers.get(targetEmail);
  user.status = 'unsubscribed';
  user.unsubscribedAt = new Date().toISOString();

  return res.send(`
    <html>
      <body style="font-family: sans-serif; text-align: center; margin-top: 50px;">
        <h2>You have been unsubscribed</h2>
        <p>The address <strong>${targetEmail}</strong> will no longer receive our newsletter.</p>
      </body>
    </html>
  `);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

---

### Best Practices Implemented:

1. **Unchecked Consent Checkbox**: In HTML, not providing the `checked` attribute ensures the user must explicitly click the box, satisfying strict privacy regulations like GDPR.
2. **Server-Side Sanitation & Normalization**: The back end uses `validator.isEmail()` to guard against SQL injections/XSS/malformed emails, and `validator.normalizeEmail()` to prevent duplicate accounts created via email alias tricks (e.g., `user+tag@gmail.com`).
3. **One-Click Unsubscribe Tokens**: Instead of requiring a user to log in or enter their password to unsubscribe, unique, unpredictable tokens (`crypto.randomBytes`) are tied to each profile. This URL can be added to the footer of every marketing email you send.

